// inventory.js
// InventorySystem: draggable stock grid, hero equipment slots, and the
// unified Pointer Event drag-and-drop that works for mouse and touch alike.

import { state } from './state.js';
import { HERO_BASE } from './data.js';
import { logLine } from './log.js';

const stockGrid = document.getElementById('stockGrid');
const slots = Array.from(document.querySelectorAll('.slot'));
const statATK = document.getElementById('statATK');
const statDEF = document.getElementById('statDEF');

let dragGhost = null;

/* ---------- Stock (draggable source items) ---------- */

export function renderStock(){
  stockGrid.innerHTML = '';
  state.stock.forEach(item => {
    const el = document.createElement('div');
    el.className = 'drag-item';
    el.dataset.uid = item.uid;
    el.innerHTML = `<div class="ic">${item.icon}</div><div class="lbl">${item.name}</div>`;
    makeDraggable(el, item);
    stockGrid.appendChild(el);
  });
}

/* ---------- Hero equipment slots ---------- */

export function renderSlots(){
  slots.forEach(slotEl => {
    const key = slotEl.dataset.slot;
    const item = state.equipped[key];
    slotEl.classList.toggle('filled', !!item);
    const label = key === 'weapon' ? 'Weapon' : key === 'armor' ? 'Armor' : 'Potion';
    if(item){
      slotEl.innerHTML = `<span class="slot-label">${label}</span>
        <div class="ic">${item.icon}</div><div class="lbl">${item.name}</div>
        <div class="remove-x" data-remove="${key}">✕</div>`;
    } else {
      slotEl.innerHTML = `<span class="slot-label">${label}</span>`;
    }
  });

  slots.forEach(slotEl => {
    const x = slotEl.querySelector('.remove-x');
    if(x) x.addEventListener('click', (e) => {
      e.stopPropagation();
      unequip(slotEl.dataset.slot);
      renderAllAfterInventoryChange();
    });
  });

  recalcHeroStats();
}

function recalcHeroStats(){
  let atk = HERO_BASE.atk, def = HERO_BASE.def;
  Object.values(state.equipped).forEach(item => {
    if(!item) return;
    if(item.atk) atk += item.atk;
    if(item.def) def += item.def;
    if(item.flaw){
      if(item.flaw.atkMod) atk += item.flaw.atkMod;
      if(item.flaw.defMod) def += item.flaw.defMod;
    }
  });
  statATK.textContent = Math.max(1, atk);
  statDEF.textContent = Math.max(0, def);
}

function unequip(slotKey){
  if(state.running) return;
  const item = state.equipped[slotKey];
  if(!item) return;
  state.equipped[slotKey] = null;
  state.stock.push(item);
}

/* ---------- Drag & drop (Pointer Events = mouse + touch in one path) ---------- */

// Set by main.js so this module can trigger a full re-render after a drop
// without importing main.js and creating a circular dependency.
let renderAllAfterInventoryChange = () => {};
export function bindRerender(fn){
  renderAllAfterInventoryChange = fn;
}

function makeDraggable(el, item){
  el.addEventListener('pointerdown', (e) => {
    if(state.running) return;
    e.preventDefault();
    el.classList.add('dragging');
    dragGhost = document.createElement('div');
    dragGhost.className = 'drag-ghost';
    dragGhost.textContent = item.icon;
    document.body.appendChild(dragGhost);
    positionGhost(e.clientX, e.clientY);
    el.setPointerCapture(e.pointerId);
  });

  el.addEventListener('pointermove', (e) => {
    if(!dragGhost) return;
    positionGhost(e.clientX, e.clientY);
    highlightSlotUnder(e.clientX, e.clientY, item);
  });

  el.addEventListener('pointerup', (e) => {
    if(!dragGhost) return;
    const slotEl = slotUnder(e.clientX, e.clientY);
    clearSlotHighlights();
    if(slotEl && isValidDrop(slotEl.dataset.slot, item)){
      equipItem(slotEl.dataset.slot, item);
    }
    cleanupDrag(el);
    renderAllAfterInventoryChange();
  });

  el.addEventListener('pointercancel', () => cleanupDrag(el));
}

function positionGhost(x, y){
  dragGhost.style.left = (x - 32) + 'px';
  dragGhost.style.top = (y - 32) + 'px';
}

function slotUnder(x, y){
  dragGhost.style.display = 'none';
  const el = document.elementFromPoint(x, y);
  dragGhost.style.display = 'flex';
  if(!el) return null;
  return el.closest('.slot');
}

function highlightSlotUnder(x, y, item){
  clearSlotHighlights();
  const slotEl = slotUnder(x, y);
  if(slotEl && isValidDrop(slotEl.dataset.slot, item)){
    slotEl.classList.add('drag-over');
  }
}

function clearSlotHighlights(){
  slots.forEach(s => s.classList.remove('drag-over'));
}

function isValidDrop(slotKey, item){
  if(slotKey === 'weapon') return item.type === 'weapon';
  if(slotKey === 'armor') return item.type === 'armor';
  if(slotKey === 'potion1' || slotKey === 'potion2') return item.type === 'potion';
  return false;
}

function equipItem(slotKey, item){
  state.stock = state.stock.filter(i => i.uid !== item.uid);
  if(state.equipped[slotKey]){
    state.stock.push(state.equipped[slotKey]);
  }
  state.equipped[slotKey] = item;

  const revenue = Math.round(item.cost * 1.6);
  state.gold += revenue;
  logLine(`Sold ${item.name} to the hero for ${revenue}g.`, 'system');
}

function cleanupDrag(el){
  if(dragGhost){ dragGhost.remove(); dragGhost = null; }
  if(el) el.classList.remove('dragging');
}

export function currentHeroStats(){
  return {
    atk: parseInt(statATK.textContent, 10),
    def: parseInt(statDEF.textContent, 10),
  };
}
