// dungeon.js
// DungeonSimulator: runs the turn-based tick simulation for a single dungeon
// attempt. Pure simulation logic — rendering/economy are handled by callers.

import { FLOORS, HERO_BASE } from './data.js';
import { state } from './state.js';
import { logLine, clearLog } from './log.js';
import { currentHeroStats } from './inventory.js';

const statHP = document.getElementById('statHP');
const hpBar = document.getElementById('hpBar');
const statFloor = document.getElementById('statFloor');

/**
 * Runs the full 5-floor dungeon attempt synchronously (log lines are
 * appended in order, no animation delay — trivial to add setTimeout
 * pacing later if you want a slower reveal).
 *
 * @returns {{ deathFloor: number|null, clearedAll: boolean, collectedMaterials: object[] }}
 */
export function simulateDungeonRun(){
  clearLog();
  const heroStats = currentHeroStats();
  let hero = { hp: HERO_BASE.maxHp, atk: heroStats.atk, def: heroStats.def };
  let potions = [state.equipped.potion1, state.equipped.potion2].filter(Boolean);
  let collectedMaterials = [];
  let deathFloor = null;
  let clearedAll = false;

  logLine('The hero descends into the dungeon...', 'system');

  for(const floorDef of FLOORS){
    logLine(`— Floor ${floorDef.floor}: ${floorDef.icon} ${floorDef.name} —`, 'floor');

    // Per-floor gear flaws (hp drain) tick before the fight starts.
    const equippedList = Object.values(state.equipped).filter(Boolean);
    equippedList.forEach(item => {
      if(item.flaw && item.flaw.hpPerFloor){
        hero.hp -= item.flaw.hpPerFloor;
        logLine(`${item.name}'s flaw (${item.flaw.label}) drains ${item.flaw.hpPerFloor} HP.`, 'dmg-hero');
      }
    });
    hero.hp = Math.max(0, hero.hp);
    if(hero.hp <= 0){
      deathFloor = floorDef.floor;
      logLine('The hero collapses before the fight even begins!', 'death');
      break;
    }

    // Auto-quaff a potion if HP is under 40% going into the fight.
    if(hero.hp < HERO_BASE.maxHp * 0.4 && potions.length > 0){
      hero = applyPotion(hero, potions.shift());
    }

    const result = fightFloor(hero, floorDef, potions);
    hero = result.hero;
    potions = result.potions;

    if(hero.hp <= 0){
      deathFloor = floorDef.floor;
      logLine(`The hero falls to the ${floorDef.name}!`, 'death');
      break;
    }

    if(result.monsterDefeated){
      collectedMaterials.push(floorDef.material);
      logLine(`${floorDef.name} defeated. Loot: ${floorDef.material.name} (worth ${floorDef.material.value}g).`, 'loot');
    }

    if(floorDef.floor === 5){
      clearedAll = true;
    }
  }

  statHP.textContent = Math.max(0, Math.round(hero.hp));
  hpBar.style.width = Math.max(0, (hero.hp / HERO_BASE.maxHp) * 100) + '%';
  statFloor.textContent = `${deathFloor ? deathFloor - 1 : 5} / 5`;

  return { deathFloor, clearedAll, collectedMaterials };
}

function fightFloor(hero, floorDef, potions){
  let monster = { hp: floorDef.hp, atk: floorDef.atk, def: floorDef.def };
  let round = 1;
  let monsterDefeated = false;

  while(round <= 12){
    const dmgToMonster = Math.max(1, hero.atk - monster.def);
    monster.hp -= dmgToMonster;
    logLine(`Round ${round}: Hero hits ${floorDef.name} for ${dmgToMonster}. (${floorDef.name} HP: ${Math.max(0, monster.hp)})`, 'dmg-mon');

    if(monster.hp <= 0){ monsterDefeated = true; break; }

    const dmgToHero = Math.max(1, monster.atk - hero.def);
    hero.hp -= dmgToHero;
    logLine(`Round ${round}: ${floorDef.name} hits hero for ${dmgToHero}. (Hero HP: ${Math.max(0, hero.hp)})`, 'dmg-hero');

    if(hero.hp <= 0){ hero.hp = 0; break; }

    // Emergency potion mid-fight.
    if(hero.hp < HERO_BASE.maxHp * 0.25 && potions.length > 0){
      hero = applyPotion(hero, potions.shift(), true);
    }

    round++;
  }

  return { hero, potions, monsterDefeated };
}

function applyPotion(hero, potion, panic = false){
  if(potion.heal){
    hero.hp = Math.min(HERO_BASE.maxHp, hero.hp + potion.heal);
    logLine(`${panic ? 'Hero panics and drinks' : 'Hero drinks'} ${potion.name}, recovers ${potion.heal} HP.`, 'loot');
  }
  if(potion.atkBoost){
    hero.atk += potion.atkBoost;
    if(potion.flaw && potion.flaw.defMod) hero.def += potion.flaw.defMod;
    logLine(`Hero drinks ${potion.name}! Attack surges to ${hero.atk}.`, 'loot');
  }
  return hero;
}
