// economy.js
// EconomyManager: resolves the sabotage payoff after a dungeon run
// (buyback rate depends on exactly where/whether the hero died), and
// owns the gold ledger + run counter display.

import { state } from './state.js';
import { logLine, clearLog } from './log.js';

const goldVal = document.getElementById('goldVal');
const runVal = document.getElementById('runVal');
const profitVal = document.getElementById('profitVal');
const resultBox = document.getElementById('resultBox');
const statHP = document.getElementById('statHP');
const hpBar = document.getElementById('hpBar');
const statFloor = document.getElementById('statFloor');

export function renderLedger(){
  goldVal.textContent = state.gold;
  runVal.textContent = state.runNumber;
}

/**
 * Applies the buyback payoff based on the run outcome and updates gold.
 * Sabotage rule: dying exactly on floor 5 (the boss) after clearing 1-4
 * is the best outcome — full materials, steep discount buyback.
 */
export function resolveRunOutcome({ deathFloor, clearedAll, collectedMaterials }){
  let buybackRate, outcomeLabel, outcomeClass;

  if(clearedAll){
    buybackRate = 0;
    outcomeLabel = 'The hero triumphed and kept every material. No buyback — the plan failed completely.';
    outcomeClass = 'death';
  } else if(deathFloor === 5){
    buybackRate = 0.85;
    outcomeLabel = 'Perfect sabotage — the hero fell to the dragon after clearing floors 1–4. Maximum buyback.';
    outcomeClass = 'sabotage';
  } else {
    buybackRate = 0.6;
    outcomeLabel = `The hero fell too early (floor ${deathFloor}). Fewer materials, smaller buyback.`;
    outcomeClass = 'win';
  }

  logLine(outcomeLabel, outcomeClass);

  let buybackTotal = 0;
  collectedMaterials.forEach(m => {
    const amt = Math.round(m.value * buybackRate);
    buybackTotal += amt;
    if(amt > 0) logLine(`Buy back ${m.name} at discount: +${amt}g`, 'loot');
  });

  state.gold += buybackTotal;

  resultBox.classList.add('show');
  resultBox.innerHTML = `
    <div class="row"><span>Materials collected</span><span>${collectedMaterials.length}</span></div>
    <div class="row"><span>Buyback rate</span><span>${Math.round(buybackRate * 100)}%</span></div>
    <div class="row"><span>Buyback earnings</span><span>+${buybackTotal}g</span></div>
    <div class="row total"><span>Run profit</span><span>${buybackTotal}g</span></div>
  `;
  profitVal.textContent = buybackTotal;

  // The run consumes whatever was equipped.
  state.equipped = { weapon:null, armor:null, potion1:null, potion2:null };
  state.running = false;
}

export function resetHero(){
  if(state.running) return;
  Object.keys(state.equipped).forEach(k => {
    if(state.equipped[k]) state.stock.push(state.equipped[k]);
    state.equipped[k] = null;
  });
  state.runNumber += 1;
  statHP.textContent = 100;
  hpBar.style.width = '100%';
  statFloor.textContent = '0 / 5';
  clearLog();
  logLine('New run ready. Equip your hero, then send them in.', 'system');
  resultBox.classList.remove('show');
}
