// shop.js
// ShopSystem: renders the buyable item list and handles purchases.
// Purchases move gold -> state.stock. Nothing here touches the hero.

import { ITEM_DB } from './data.js';
import { state, cryptoRandomId } from './state.js';

const shopList = document.getElementById('shopList');

export function renderShop(onChange){
  shopList.innerHTML = '';
  ITEM_DB.forEach(item => {
    const row = document.createElement('div');
    row.className = 'shop-item';
    row.innerHTML = `
      <div class="icon">${item.icon}</div>
      <div class="info">
        <div class="name">${item.name}</div>
        <div class="tags">${item.type.toUpperCase()} · ${item.tag}</div>
        ${item.flaw ? `<div class="flaw">⚠ ${item.flaw.label}</div>` : ''}
      </div>
      <button class="buy-btn" data-id="${item.id}">${item.cost}g</button>
    `;
    shopList.appendChild(row);
  });

  shopList.querySelectorAll('.buy-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      buyItem(btn.dataset.id);
      onChange();
    });
  });

  updateBuyButtons();
}

export function updateBuyButtons(){
  shopList.querySelectorAll('.buy-btn').forEach(btn => {
    const item = ITEM_DB.find(i => i.id === btn.dataset.id);
    btn.disabled = state.gold < item.cost || state.running;
  });
}

function buyItem(id){
  if(state.running) return;
  const item = ITEM_DB.find(i => i.id === id);
  if(state.gold < item.cost) return;
  state.gold -= item.cost;
  state.stock.push({ uid: cryptoRandomId(), ...item });
}
