// main.js
// GameManager: the composition root. Wires ShopSystem, InventorySystem,
// DungeonSimulator, and EconomyManager together and owns the render loop.

import { state } from './state.js';
import { renderShop, updateBuyButtons } from './shop.js';
import { renderStock, renderSlots, bindRerender } from './inventory.js';
import { simulateDungeonRun } from './dungeon.js';
import { renderLedger, resolveRunOutcome, resetHero } from './economy.js';

const runBtn = document.getElementById('runBtn');
const resetBtn = document.getElementById('resetBtn');

function renderAll(){
  renderLedger();
  renderStock();
  renderSlots();
  updateBuyButtons();
  const hasGear = state.equipped.weapon || state.equipped.armor
    || state.equipped.potion1 || state.equipped.potion2;
  runBtn.disabled = state.running || !hasGear;
}

// Inventory drag-drop needs to trigger a full re-render after a successful
// equip/unequip without importing main.js back into inventory.js.
bindRerender(renderAll);

function handleRunDungeon(){
  if(state.running) return;
  state.running = true;
  runBtn.disabled = true;
  updateBuyButtons();

  const outcome = simulateDungeonRun();
  resolveRunOutcome(outcome);

  renderAll();
}

function handleReset(){
  resetHero();
  renderAll();
}

runBtn.addEventListener('click', handleRunDungeon);
resetBtn.addEventListener('click', handleReset);

// Initial paint
renderShop(renderAll);
renderAll();
