// state.js
// The single mutable game state object. Every module reads/writes through here
// so there is one source of truth (mirrors a lightweight GameManager store).

export const state = {
  gold: 80,
  runNumber: 1,
  stock: [],       // items purchased but not yet equipped
  equipped: { weapon:null, armor:null, potion1:null, potion2:null },
  running: false,  // true while a dungeon run is animating/resolving
};

export function cryptoRandomId(){
  return 'i' + Math.random().toString(36).slice(2, 10);
}
